import{c as r,$ as d,Q as i,j as c,g as e,n as s,o,m as p}from"./chunks/framework.CWBTDBPu.js";const _=JSON.parse('{"title":"YuTeleport 安装部署","description":"","frontmatter":{"title":"YuTeleport 安装部署"},"headers":[],"relativePath":"plugins/items/yu-teleport/install.md","filePath":"plugins/items/yu-teleport/install.md"}'),n={name:"plugins/items/yu-teleport/install.md"},h={class:"quick-actions"};function u(m,t,b,y,g,P){const a=d("CopyMarkdownButton"),l=d("CopyLLMButton");return i(),c("div",null,[t[0]||(t[0]=e("h1",{id:"yuteleport-安装部署",tabindex:"-1"},[s("YuTeleport 安装部署 "),e("a",{class:"header-anchor",href:"#yuteleport-安装部署","aria-label":'Permalink to "YuTeleport 安装部署"'},"​")],-1)),e("div",h,[o(a,{page:""}),o(l,{page:""})]),t[1]||(t[1]=p('<h2 id="环境要求" tabindex="-1">环境要求 <a class="header-anchor" href="#环境要求" aria-label="Permalink to &quot;环境要求&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>Java</td><td>Java 8 及以上。源码通过 <code>options.release = 8</code> 编译。</td></tr><tr><td>服务端</td><td>Bukkit、Spigot、Paper、Purpur、Folia，以及 Mohist、Arclight、Youer 等兼容 Bukkit API 的混合端。</td></tr><tr><td>Minecraft</td><td>目标适配 <code>1.8.x-1.26.x</code>。源码以 Spigot API <code>1.8-R0.1-SNAPSHOT</code> 为编译基线，通过反射兼容新版 API。</td></tr><tr><td>经济扣费</td><td>可选。<code>economy.provider: vault</code> 需要 Vault 和经济插件，<code>playerpoints</code> 需要 PlayerPoints。</td></tr><tr><td>PlaceholderAPI</td><td>可选。安装后可注册 <code>%yuteleport_*%</code> 变量。</td></tr><tr><td>网络访问</td><td>bStats 和更新检查会访问外部服务；核心传送功能不依赖外网。</td></tr></tbody></table><h2 id="从源码构建" tabindex="-1">从源码构建 <a class="header-anchor" href="#从源码构建" aria-label="Permalink to &quot;从源码构建&quot;">​</a></h2><p>在 <code>YuTeleport</code> 源码目录执行：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">gradlew.bat</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> shadowJar</span></span></code></pre></div><p>构建完成后优先使用 <code>build/libs/</code> 下的 <code>YuTeleport-2.0.0.0-all.jar</code> 或同版本 shadowJar 产物。该产物会重定位 bStats 与 YuLib，避免多个 Yu 系插件携带不同版本运行库时发生类冲突。</p><h2 id="部署到服务端" tabindex="-1">部署到服务端 <a class="header-anchor" href="#部署到服务端" aria-label="Permalink to &quot;部署到服务端&quot;">​</a></h2><ol><li>停止服务端。</li><li>将 <code>YuTeleport-2.0.0.0-all.jar</code> 放入服务端 <code>plugins/</code> 目录。</li><li>启动服务端，等待生成 <code>plugins/YuTeleport/config.yml</code>、<code>lang/zh_CN.yml</code>、<code>lang/en_US.yml</code>。</li><li>控制台会输出官方文档、Modrinth、Issue、QQ 群和爱发电链接。</li><li>进入游戏执行 <code>/rtp help</code>、<code>/ytp help</code> 或 <code>/yuteleport help</code> 检查主命令。</li><li>按需测试 <code>/warp</code>、<code>/home</code>、<code>/tpa</code> 等模块命令是否已按配置注册。</li></ol><h2 id="首次配置检查" tabindex="-1">首次配置检查 <a class="header-anchor" href="#首次配置检查" aria-label="Permalink to &quot;首次配置检查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>默认位置</th><th>建议</th></tr></thead><tbody><tr><td>世界访问</td><td><code>teleports.defaults.world-access</code></td><td>将登录服、主城、大厅等世界加入黑名单；资源世界可改用白名单。</td></tr><tr><td>RTP 范围</td><td><code>teleports.rtp.worlds.default.radius</code></td><td>根据资源世界大小设置 <code>min</code> 和 <code>max</code>。</td></tr><tr><td>安全检查</td><td><code>teleports.rtp.worlds.default.safety</code></td><td>正式服建议保持开启，必要时按世界覆盖。</td></tr><tr><td>等待与打断</td><td><code>teleports.defaults.warmup-seconds</code>、<code>cancel-triggers</code></td><td>生存/PVP 服务器建议保留等待和移动打断。</td></tr><tr><td>经济</td><td><code>economy</code>、各模块 <code>cost</code></td><td>先确认 Vault 或 PlayerPoints 可用，再配置费用。</td></tr><tr><td>冷却持久化</td><td><code>cooldowns.persist</code></td><td>正式服建议保留 <code>true</code>，重启后继续保留未到期冷却。</td></tr><tr><td>模块开关</td><td><code>teleports.rtp/warp/home/tpa/share.enabled</code></td><td>不需要的模块可关闭，关闭后不会注册对应命令。</td></tr><tr><td>配置更新模式</td><td><code>config-update-mode</code></td><td><code>template</code> 会同步模板注释和顺序，<code>preserve</code> 会尽量保留现有排版。</td></tr></tbody></table><h2 id="官方链接" tabindex="-1">官方链接 <a class="header-anchor" href="#官方链接" aria-label="Permalink to &quot;官方链接&quot;">​</a></h2><p>默认配置和插件启动日志内置这些入口：</p><table tabindex="0"><thead><tr><th>入口</th><th>地址</th></tr></thead><tbody><tr><td>官方文档 Wiki</td><td><code>https://vicuna-main.github.io/YuPluginHub/plugins/items/yu-teleport/</code></td></tr><tr><td>Modrinth 下载</td><td><code>https://modrinth.com/plugin/yuteleport</code></td></tr><tr><td>Bug / Issue 反馈</td><td><code>https://github.com/vicuna-main/YuTeleportIssueReport</code></td></tr><tr><td>官方 QQ 交流群</td><td><code>https://qm.qq.com/q/xiwJYBYdh0</code></td></tr><tr><td>爱发电支持</td><td><code>https://afdian.com/a/vicuna</code></td></tr></tbody></table><h2 id="升级已有-yurtp-yuteleport" tabindex="-1">升级已有 YuRTP/YuTeleport <a class="header-anchor" href="#升级已有-yurtp-yuteleport" aria-label="Permalink to &quot;升级已有 YuRTP/YuTeleport&quot;">​</a></h2><ol><li>停服备份 <code>plugins/YuTeleport/</code>，旧 YuRTP 用户也应备份旧插件目录。</li><li>替换 jar。</li><li>启动一次服务端，让插件按 <code>config-version: 19</code> 合并配置。</li><li>检查 <code>config.yml.bak&lt;旧版本号&gt;-&lt;时间戳&gt;</code> 备份。</li><li>依次测试 <code>/rtp</code>、<code>/yuteleport reload</code>、一次管理员代传送、一次 warp/home/tpa 流程。</li><li>如果使用 PAPI，执行 <code>/papi parse me %yuteleport_status%</code> 检查变量注册。</li></ol><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><ol><li>停止服务端。</li><li>删除 <code>plugins/</code> 中的 YuTeleport jar。</li><li>如不再需要配置和数据，删除 <code>plugins/YuTeleport/</code> 目录。</li></ol><p>插件本体不创建数据库表；经济数据由 Vault 或 PlayerPoints 对应插件维护。</p>',18))])}const f=r(n,[["render",u]]);export{_ as __pageData,f as default};
